sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    var body = request.body.data;
    var text = body.description_text || '';

    if (!text) {
        response.setStatus(400);
        response.setBody({ error: 'description_text is required' });
        return;
    }

    var utils = new x_2145749_qc.VaAgentUtils();
    var result = utils.needsHumanEscalation(text);

    response.setStatus(200);
    response.setBody({
        result: {
            needs_escalation: result.needsEscalation,
            reason: result.reason,
            recommendation: result.needsEscalation
                ? 'Route to human agent. Create case with priority 1 and flag for personal follow-up.'
                : 'Safe for automated handling. Proceed with normal prediction and resolution flow.'
        }
    });
})(request, response)
